@Test(timeout = 3000)
 public void testShouldGetTwoFrgamentsIfTwoBookiesFailedInSameEnsemble()
 throws Exception {

 LedgerHandle lh = bkc.createLedger(3, 2, BookKeeper.DigestType.CRC32,
 TEST_LEDGER_PASSWORD);
 startNewBookie();
 startNewBookie();
 lh.addEntry(TEST_LEDGER_ENTRY_DATA);

 ArrayList<BookieSocketAddress> firstEnsemble = lh.getLedgerMetadata()
 .getEnsembles().get(0L);

 BookieSocketAddress firstBookieFromEnsemble = firstEnsemble.get(0);
 killBookie(firstEnsemble, firstBookieFromEnsemble);

 BookieSocketAddress secondBookieFromEnsemble = firstEnsemble.get(1);
 killBookie(firstEnsemble, secondBookieFromEnsemble);
 lh.addEntry(TEST_LEDGER_ENTRY_DATA);
 Set<LedgerFragment> result = getUnderReplicatedFragments(lh);

 assertNotNull("Result shouldn't be null", result);

 for (LedgerFragment r : result) {
 LOG.info("unreplicated fragment: {}", r);
 }

 assertEquals("There should be 2 fragments", 2, result.size());
 }

@Test
 public void testSave() throws IOException {
 final String comments = "Hello world!";
 // actual
 try (ByteArrayOutputStream actual = new ByteArrayOutputStream()) {
 PropertiesFactory.EMPTY_PROPERTIES.save(actual, comments);
 // expected
 try (ByteArrayOutputStream expected = new ByteArrayOutputStream()) {
 PropertiesFactory.INSTANCE.createProperties().save(expected, comments);

 // Properties.save stores the specified comment appended with current time stamp in the next line
 String expectedComment = getFirstLine(expected.toString("UTF-8"));
 String actualComment = getFirstLine(actual.toString("UTF-8"));
 assertEquals(expectedComment, actualComment, () ->
 String.format("Expected String '%s' with length '%s'", expectedComment, expectedComment.length()));
 expected.reset();
 try (PrintStream out = new PrintStream(expected)) {
 new Properties().save(out, comments);
 }
 assertArrayEquals(expected.toByteArray(), actual.toByteArray(), expected::toString);
 } catch (UnsupportedEncodingException e) {
 fail(e.getMessage(), e);
 }
 }
 }

@Test(timeout=60000)
 public void testSlowBookie() throws Exception {
 ClientConfiguration conf = new ClientConfiguration();
 conf.setZkServers(zkUtil.getZooKeeperConnectString()).setReadTimeout(360);

 BookKeeper bkc = new BookKeeper(conf);

 LedgerHandle lh = bkc.createLedger(4, 3, 2, BookKeeper.DigestType.CRC32, new byte[] {});

 byte[] entry = "Test Entry".getBytes();
 for (int i = 0; i < 10; i++) {
 lh.addEntry(entry);
 }
 final CountDownLatch b0latch = new CountDownLatch(1);
 final CountDownLatch b1latch = new CountDownLatch(1);
 List<InetSocketAddress> curEns = lh.getLedgerMetadata().currentEnsemble;
 try {
 sleepBookie(curEns.get(0), b0latch);
 for (int i = 0; i < 10; i++) {
 lh.addEntry(entry);
 }
 sleepBookie(curEns.get(2), b1latch); // should cover all quorums

 final AtomicInteger i = new AtomicInteger(0xdeadbeef);
 AsyncCallback.AddCallback cb = new AsyncCallback.AddCallback() {
 public void addComplete(int rc, LedgerHandle lh, long entryId, Object ctx) {
 i.set(rc);
 }
 };
 lh.asyncAddEntry(entry, cb, null);

 Thread.sleep(1000); // sleep a second to allow time to complete
 assertEquals(i.get(), 0xdeadbeef);
 b0latch.countDown();
 b1latch.countDown();
 Thread.sleep(2000);
 assertEquals(i.get(), BKException.Code.OK);
 } finally {
 b0latch.countDown();
 b1latch.countDown();
 }
 }

